/**
 * focms-swim-page.js
 * ===================
 * Hydrates the Swimming page (johnrjordan.com/swimming, post ID 20) from
 * the public FOCMS feed at /focms-feed-swim-bests/ (post ID 997).
 *
 * The feed JSON is the single source of truth for swim bests, standards,
 * NCAA reference times, and the server-computed Power Index. The feed is
 * generated by a Postgres → WP regen script that has the bearer token;
 * the browser never sees the token because the feed page is public.
 *
 * What this script does on a page that has data-focms-swim-page="1":
 *  1. Fetches /focms-feed-swim-bests/ (with a cache-buster).
 *  2. Parses the JSON from the <pre> tag inside.
 *  3. For every row in every .sw-table:
 *       - reads data-event="..." (e.g. "50 Free LCM")
 *       - looks up best in feed.bests[event]
 *       - fills .bt, .ptcol, .std, .nextstd, .tn, .drop, .pct, .age cells
 *  4. Renders a Power Index panel into [data-focms-power-index].
 *
 * NO INLINE SCRIPT on the page. NO && operators (defensive — file is .js,
 * not Custom HTML, so wptexturize cannot touch it, but kept clean anyway).
 *
 * This file lives in the focms-dashboard plugin under
 *   assets/js/focms-swim-page.js
 * and is enqueued by focms-dashboard.php only when is_page(20).
 *
 * Version: 1.0.0  (2026-06-22)
 */
(function () {
  'use strict';

  // -----------------------------------------------------------------
  // Configuration
  // -----------------------------------------------------------------
  var FEED_URL = '/focms-feed-swim-bests/';
  var BIRTH_DATE = '2014-08-29';      // John's DOB; used for age-at-swim calc
  var TIER_ORDER = ['AAAA','AAA','AA','A','BB','B','C'];  // fastest to slowest

  // -----------------------------------------------------------------
  // Bootstrap
  // -----------------------------------------------------------------
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }

  function init() {
    var marker = document.querySelector('[data-focms-swim-page="1"]');
    if (!marker) {
      // Page isn't tagged for hydration; bail silently.
      return;
    }
    fetchFeed()
      .then(applyToPage)
      .catch(function (err) {
        console.error('[focms-swim-page] hydration failed:', err);
        var status = document.querySelector('[data-focms-status]');
        if (status) {
          status.textContent = 'Could not load latest times. Showing static fallback.';
          status.style.color = '#c00';
        }
      });
  }

  // -----------------------------------------------------------------
  // Feed fetch
  // -----------------------------------------------------------------
  function fetchFeed() {
    var url = FEED_URL + '?cb=' + Date.now();
    return fetch(url, { credentials: 'omit', cache: 'no-store' })
      .then(function (r) {
        if (!r.ok) {
          throw new Error('HTTP ' + r.status + ' fetching feed');
        }
        return r.text();
      })
      .then(function (html) {
        // The feed page wraps JSON inside <pre>...</pre> from a Code block.
        var doc = new DOMParser().parseFromString(html, 'text/html');
        var pre = doc.querySelector('pre');
        if (!pre) {
          throw new Error('feed page missing <pre> with JSON');
        }
        return JSON.parse(pre.textContent.trim());
      });
  }

  // -----------------------------------------------------------------
  // Apply feed to the DOM
  // -----------------------------------------------------------------
  function applyToPage(feed) {
    if (!feed || !feed.bests) {
      throw new Error('feed missing .bests');
    }

    var rows = document.querySelectorAll('.sw-table tbody tr[data-event]');
    var hydrated = 0;
    rows.forEach(function (tr) {
      var eventKey = tr.getAttribute('data-event');  // e.g. "50 Free LCM"
      var best = feed.bests[eventKey];
      if (!best) {
        // No record for this event in the feed; leave row blank but mark.
        tr.classList.add('focms-no-data');
        return;
      }
      fillRow(tr, eventKey, best);
      hydrated++;
    });

    renderPowerIndex(feed.power_index);
    renderMeta(feed._meta, hydrated, rows.length);
  }

  function fillRow(tr, eventKey, best) {
    setCell(tr, '.bt',       best.time || formatTime(best.seconds));
    setCell(tr, '.ptcol',    best.points != null ? best.points : '');
    setCell(tr, '.std',      best.usa_standard || '—');
    setCell(tr, '.nextstd',  best.next_std || '—');

    // Time Needed = current bt seconds - next_time_seconds (positive = needs to drop)
    var tn = '—';
    if (best.next_time_seconds != null && best.seconds != null) {
      var delta = best.seconds - best.next_time_seconds;
      tn = delta > 0 ? formatDelta(delta) : '—';
    }
    setCell(tr, '.tn', tn);

    // Drop and % from data-first-time on the row
    var firstStr = tr.getAttribute('data-first-time');
    var firstSec = parseTimeToSeconds(firstStr);
    var btSec    = best.seconds;
    var dropTxt = '—', pctTxt = '—';
    if (firstSec != null && btSec != null && firstSec > 0) {
      var drop = firstSec - btSec;
      dropTxt = formatDelta(drop);
      pctTxt  = ((drop / firstSec) * 100).toFixed(1) + '%';
    }
    setCell(tr, '.drop', dropTxt);
    setCell(tr, '.pct',  pctTxt);

    // Age at swim from best.date and BIRTH_DATE
    setCell(tr, '.age', ageAt(best.date));

    // Meet column comes from feed if present; otherwise leave whatever's there
    if (best.meet) {
      setCell(tr, '.mt', best.meet);
    }
  }

  function setCell(tr, sel, value) {
    var cell = tr.querySelector(sel);
    if (cell) cell.textContent = String(value);
  }

  // -----------------------------------------------------------------
  // Power Index panel
  // -----------------------------------------------------------------
  function renderPowerIndex(pi) {
    var panel = document.querySelector('[data-focms-power-index]');
    if (!panel) return;
    if (!pi || pi.value == null) {
      panel.innerHTML = '<p class="focms-pi-empty">Power Index unavailable.</p>';
      return;
    }
    var topRows = (pi.top_4 || []).map(function (e) {
      return '<li><span class="ev">' + escapeHTML(e.event_course) + '</span>'
           + '<span class="pp">' + Number(e.pp).toFixed(2) + '</span></li>';
    }).join('');
    var src = pi.base_times_source || {};
    panel.innerHTML =
      '<div class="focms-pi-card">'
    +   '<div class="focms-pi-headline">'
    +     '<span class="focms-pi-label">Power Index</span>'
    +     '<span class="focms-pi-value">' + Number(pi.value).toFixed(1) + '</span>'
    +   '</div>'
    +   '<div class="focms-pi-sub">'
    +     'Swimcloud-style, lower is better. '
    +     'Computed from ' + (pi.total_eligible_events || 0) + ' eligible events.'
    +   '</div>'
    +   '<ol class="focms-pi-top">' + topRows + '</ol>'
    +   '<div class="focms-pi-cite">'
    +     'Source: <a href="' + escapeAttr(src.source_url || '#')
    +     '" target="_blank" rel="noopener">NCAA D1 Men ' + (src.effective_year || '')
    +     ' Qualifying Standards</a> &middot; refreshed ' + escapeHTML(src.refreshed_at || '')
    +   '</div>'
    + '</div>';
  }

  function renderMeta(meta, hydrated, total) {
    var status = document.querySelector('[data-focms-status]');
    if (!status || !meta) return;
    status.textContent = 'Hydrated ' + hydrated + '/' + total
      + ' rows from FOCMS feed schema ' + (meta.schema_version || '?')
      + ' (age group ' + (meta.current_age_group || '?') + ').';
  }

  // -----------------------------------------------------------------
  // Helpers
  // -----------------------------------------------------------------
  function parseTimeToSeconds(s) {
    if (!s || typeof s !== 'string') return null;
    s = s.trim();
    if (!s) return null;
    if (s.indexOf(':') === -1) {
      var n = parseFloat(s);
      return isNaN(n) ? null : n;
    }
    var parts = s.split(':');
    var min = parseFloat(parts[0]);
    var sec = parseFloat(parts[1]);
    if (isNaN(min) || isNaN(sec)) return null;
    return min * 60 + sec;
  }

  function formatTime(seconds) {
    if (seconds == null || isNaN(seconds)) return '';
    if (seconds < 60) return seconds.toFixed(2);
    var m = Math.floor(seconds / 60);
    var s = (seconds - m * 60).toFixed(2);
    if (parseFloat(s) < 10) s = '0' + s;
    return m + ':' + s;
  }

  function formatDelta(seconds) {
    if (seconds == null || isNaN(seconds)) return '—';
    if (seconds < 60) return seconds.toFixed(2);
    var m = Math.floor(seconds / 60);
    var s = (seconds - m * 60).toFixed(2);
    if (parseFloat(s) < 10) s = '0' + s;
    return m + ':' + s;
  }

  function ageAt(dateStr) {
    if (!dateStr) return '—';
    var swim = new Date(dateStr);
    var dob  = new Date(BIRTH_DATE);
    if (isNaN(swim.getTime()) || isNaN(dob.getTime())) return '—';
    var age = swim.getFullYear() - dob.getFullYear();
    var m = swim.getMonth() - dob.getMonth();
    var didBirthday = m > 0 || (m === 0 && swim.getDate() >= dob.getDate());
    if (!didBirthday) age--;
    return String(age);
  }

  function escapeHTML(s) {
    return String(s == null ? '' : s)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');
  }

  function escapeAttr(s) {
    return escapeHTML(s).replace(/'/g, '&#39;');
  }
})();
